"use client";
import { useState, useEffect } from "react";
import axios from "axios";
import Sidebar from "../../components/sidebar";
import Navbar from "../../components/Navbar";

export default function Comptes() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedUsers, setSelectedUsers] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(10); // Par défaut 10 éléments par page

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/loginc")
      .then((response) => {
        setUsers(response.data);
        setLoading(false);
      })
      .catch(() => {
        setError("Erreur de chargement des comptes.");
        setLoading(false);
      });
  }, []);

  if (loading) return <p className="text-center text-gray-500">Chargement en cours...</p>;
  if (error) return <p className="text-center text-red-500">{error}</p>;

  const sendEmail = async (email, password) => {
    try {
      await axios.post("http://localhost:5000/api/send-email", {
        email,
        subject: "Informations de Connexion à l'App",
        body: `Votre mot de passe est ${password}. Vous pouvez vous connecter en suivant ce lien: http://localhost:3000`,
      });
      alert(`Email envoyé avec succès à ${email}`);
    } catch (error) {
      alert(`Erreur lors de l'envoi de l'email à ${email}`);
    }
  };

  const sendEmailToSelected = async () => {
    try {
      for (const userId of selectedUsers) {
        const user = users.find((user) => user.id === userId);
        if (user) {
          await sendEmail(user.email, user.password);
        }
      }
      alert("Emails envoyés avec succès aux utilisateurs sélectionnés");
    } catch (error) {
      alert("Erreur lors de l'envoi des emails");
    }
  };

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      setSelectedUsers(users.map((user) => user.id));
    } else {
      setSelectedUsers([]);
    }
  };

  const handleSelectUser = (userId) => {
    setSelectedUsers((prevState) =>
      prevState.includes(userId)
        ? prevState.filter((id) => id !== userId)
        : [...prevState, userId]
    );
  };

  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentUsers = users.slice(indexOfFirstItem, indexOfLastItem);
  const totalPages = Math.ceil(users.length / itemsPerPage);

  const paginate = (pageNumber) => setCurrentPage(pageNumber);
  const handleItemsPerPageChange = (e) => {
    setItemsPerPage(Number(e.target.value));
    setCurrentPage(1); // Réinitialiser à la première page
  };

  return (
    <div className="flex h-screen min-h-screen w-screen bg-gray-50">
      <Sidebar className="h-screen hidden lg:block" />
      <div className="w-full flex flex-col h-screen">
        <Navbar />
        <div className="w-full flex-1 py-3 px-4 overflow-hidden">
          <h1 className="text-3xl font-semibold mb-4 text-center text-gray-800">
            Liste des comptes
          </h1>

          <div className="text-center mb-3">
            <button
              onClick={sendEmailToSelected}
              className="bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 transition duration-300 shadow-md"
            >
              Envoyer Email aux utilisateurs sélectionnés
            </button>
          </div>

          <div className="text-center mb-3">
            <label className="inline-flex items-center">
              <input
                type="checkbox"
                onChange={handleSelectAll}
                checked={selectedUsers.length === users.length}
                className="form-checkbox h-5 w-5 text-blue-600 rounded"
              />
              <span className="ml-2 text-lg text-gray-700">Sélectionner tout</span>
            </label>
          </div>

          <div className="bg-white rounded-xl shadow-lg overflow-hidden">
            <div className="max-h-[700px] overflow-y-auto">
              <table className="w-full">
                <thead className="bg-gradient-to-r from-blue-500 to-blue-600 sticky top-0">
                  <tr>
                    <th className="p-4 text-left text-white">Sélectionner</th>
                    <th className="p-4 text-left text-white">ID</th>
                    <th className="p-4 text-left text-white">ID user</th>
                    <th className="p-4 text-left text-white">Email</th>
                    <th className="p-4 text-left text-white">Mot de Passe</th>
                    <th className="p-4 text-left text-white">Rôle</th>
                    <th className="p-4 text-center text-white">Envoyer Email</th>
                  </tr>
                </thead>
                <tbody>
                  {currentUsers.length > 0 ? (
                    currentUsers.map((user, index) => (
                      <tr
                        key={user.id}
                        className={`border-b border-gray-100 hover:bg-gray-50 transition ${
                          index % 2 === 0 ? "bg-gray-50" : "bg-white"
                        }`}
                      >
                        <td className="p-4 text-gray-800">
                          <input
                            type="checkbox"
                            checked={selectedUsers.includes(user.id)}
                            onChange={() => handleSelectUser(user.id)}
                            className="form-checkbox h-5 w-5 text-blue-600 rounded"
                          />
                        </td>
                        <td className="p-4 text-gray-800">{user.id}</td>
                        <td className="p-4 text-gray-800">{user.user_id}</td>
                        <td className="p-4 text-gray-800">{user.email}</td>
                        <td className="p-4 text-gray-800">{user.password}</td>
                        <td className="p-4 text-gray-800">{user.role}</td>
                        <td className="p-4 text-center flex justify-center space-x-3">
                          <button
                            onClick={() => sendEmail(user.email, user.password)}
                            className="text-indigo-600 hover:text-indigo-700 font-medium"
                          >
                            Envoyer Email
                          </button>
                        </td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan={7} className="p-4 text-center text-gray-500">
                        Aucun compte trouvé.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>

          {/* Pagination */}
          <div className="flex justify-between items-center p-4 bg-gradient-to-r from-blue-50 to-gray-50">
            <select
              onChange={handleItemsPerPageChange}
              value={itemsPerPage}
              className="border p-2 rounded-lg shadow-sm"
            >
              <option value={10}>10 par page</option>
              <option value={15}>15 par page</option>
              <option value={20}>20 par page</option>
            </select>
            <div className="flex space-x-2">
              {Array.from({ length: totalPages }, (_, index) => (
                <button
                  key={index}
                  onClick={() => paginate(index + 1)}
                  className={`px-4 py-2 text-sm rounded-lg ${
                    currentPage === index + 1
                      ? "bg-blue-600 text-white"
                      : "bg-white text-blue-600"
                  }`}
                >
                  {index + 1}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}